import{_ as i,C as a,o as n,c as l,a6 as t,E as s,w as d}from"./chunks/framework.CswKMrA6.js";const v=JSON.parse('{"title":"Preview Your YAML","description":"See LCARdS YAML (a card, a view or a whole dashboard) as real cards in your browser before you paste it into Home Assistant, from pasted YAML or a preview link an AI assistant made.","frontmatter":{"aside":false,"sidebar":false,"pageClass":"demo-wide","description":"See LCARdS YAML (a card, a view or a whole dashboard) as real cards in your browser before you paste it into Home Assistant, from pasted YAML or a preview link an AI assistant made."},"headers":[],"relativePath":"getting-started/preview.md","filePath":"getting-started/preview.md","lastUpdated":1794740974000}'),h={name:"getting-started/preview.md"};function p(c,e,u,w,m,g){const r=a("PreviewBoard"),o=a("ClientOnly");return n(),l("div",null,[e[0]||(e[0]=t('<h1 id="preview-your-yaml" tabindex="-1">Preview Your YAML <a class="header-anchor" href="#preview-your-yaml" aria-label="Permalink to &quot;Preview Your YAML&quot;">​</a></h1><p><strong>Paste LCARdS YAML below, or open a preview link, to see it as real cards before you put it on a dashboard.</strong> The cards are the same LCARdS bundle your Home Assistant runs, on sample states.</p><ul><li><strong>Works with</strong> one card, a view, or a whole dashboard: a dashboard with several views gets a tab for each.</li><li><strong>Private:</strong> the YAML stays in your browser. A preview link carries it after the <code>#</code>, a part of the address that browsers never send to a server.</li><li><strong>Sample states:</strong> entities you name get a believable state for their domain (a light on or off, a sensor with a number), so the values are examples. Taps on toggles and sliders change them, as in the <a href="./live-demo.html">live demo</a>.</li></ul>',3)),s(o,null,{default:d(()=>[s(r)]),_:1}),e[1]||(e[1]=t('<h2 id="preview-links-from-an-ai-assistant" tabindex="-1">Preview links from an AI assistant <a class="header-anchor" href="#preview-links-from-an-ai-assistant" aria-label="Permalink to &quot;Preview links from an AI assistant&quot;">​</a></h2><p><strong>When Claude with the <a href="./ai-assistance.html">LCARdS skill</a> designs a dashboard with you, it can give you a link to this page with the YAML inside.</strong> Open it to see the draft before you paste anything.</p><ul><li>Claude makes the link when it can run code (Claude Code, or claude.ai and the Claude apps with code execution turned on). Without that, it gives you the YAML: paste it above.</li><li>A link for a big dashboard is long. If the chat cuts it off, the page says the link couldn&#39;t be read; paste the YAML instead.</li><li><strong>Copy link to this preview</strong> makes a link for whatever is in the editor, to share or keep.</li></ul><h2 id="what-a-preview-can-t-show" tabindex="-1">What a preview can&#39;t show <a class="header-anchor" href="#what-a-preview-can-t-show" aria-label="Permalink to &quot;What a preview can&#39;t show&quot;">​</a></h2><p><strong>A preview is a close look, not your dashboard: your own states, theme and other cards aren&#39;t here.</strong></p><ul><li><strong>Other cards:</strong> cards that aren&#39;t LCARdS (tiles, entities, custom cards from HACS) show as an empty space the size of the card.</li><li><strong>Your theme:</strong> cards show LCARdS&#39; default colours, as on a dashboard without a theme. Your theme&#39;s own colours appear once the YAML is on your dashboard.</li><li><strong>Strategies:</strong> a dashboard strategy such as the LCARS shell builds its views inside Home Assistant, so it can&#39;t be previewed here.</li><li><strong>Problems in the YAML:</strong> the page runs the <a href="./config-checker.html">config checker</a> and says how many errors and warnings it found; fix those first, as the preview may differ from Home Assistant until they&#39;re gone.</li></ul>',6))])}const A=i(h,[["render",p]]);export{v as __pageData,A as default};
